def main() -> None:
    data = json.loads(ANALYSIS_PATH.read_text(encoding="utf-8"))
    # 1. Inject faithful Chinese translations into all 60 slice notes
    slice_notes = data.setdefault("slice_notes", {})
    for sid, zh in TRANSLATIONS_ZH.items():
        slice_notes.setdefault(sid, {})["translation_zh"] = zh

    # 2. Upgrade figure_notes with subpanels, caption_zh, context_connection, insert_after_slice
    data["figure_notes"] = RICH_FIGURE_NOTES

    # 3. Inject interactive Mind Map
    data["mindmap"] = MINDMAP

    ANALYSIS_PATH.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"Updated {ANALYSIS_PATH}: {len(TRANSLATIONS_ZH)} translations, {len(RICH_FIGURE_NOTES)} rich figures, {len(MINDMAP['branches'])} mindmap branches.")


if __name__ == "__main__":
    main()
